use std::str::FromStr;

use codama_nodes::Number;
use heck::ToShoutySnakeCase;
use heck::ToSnakeCase;
use heck::ToUpperCamelCase;

use crate::error::RenderError;
use crate::error::Result;

pub(crate) const GENERATED_HEADER: &str = r"//! This code was AUTOGENERATED by `pina_cpi_renderer`.
//! Please DO NOT EDIT THIS FILE directly.
//! Regenerate it from Codama IDLs instead.
#![allow(
	clippy::doc_lazy_continuation,
	clippy::empty_line_after_doc_comments,
	clippy::too_many_arguments
)]
";

pub(crate) fn page(body: &str) -> String {
	format!("{GENERATED_HEADER}\n{body}\n")
}

pub(crate) fn pascal(value: &str) -> String {
	value.to_upper_camel_case()
}

pub(crate) fn snake(value: &str) -> String {
	value.to_snake_case()
}

pub(crate) fn shouty(value: &str) -> String {
	value.to_shouty_snake_case()
}

pub(crate) fn program_id_const_name(program_name: &str) -> String {
	shouty(program_name) + "_ID"
}

pub(crate) fn rust_string_literal(value: &str) -> String {
	format!("{value:?}")
}

pub(crate) fn render_docs(docs: &[String], indent_level: usize) -> Vec<String> {
	docs.iter()
		.flat_map(|doc| render_doc(doc, indent_level))
		.collect()
}

pub(crate) fn render_doc(doc: &str, indent_level: usize) -> Vec<String> {
	let indent = "\t".repeat(indent_level);
	doc.split('\n')
		.map(|line| {
			let line = line.strip_suffix('\r').unwrap_or(line);
			format!("{indent}/// {line}")
		})
		.collect()
}

pub(crate) fn canonical_pubkey(value: &str, context: &str) -> Result<String> {
	solana_pubkey::Pubkey::from_str(value)
		.map(|public_key| public_key.to_string())
		.map_err(|error| {
			RenderError::UnsupportedValue {
				context: context.to_string(),
				kind: "publicKeyValueNode",
				reason: format!("invalid public key: {error}"),
			}
		})
}

pub(crate) fn cast_unsigned(value: &Number, max: u128, context: &str) -> Result<u128> {
	let parsed = match value {
		Number::UnsignedInteger(value) => u128::from(*value),
		Number::SignedInteger(value) => {
			u128::try_from(*value).map_err(|_| {
				RenderError::UnsupportedValue {
					context: context.to_string(),
					kind: "numberValueNode",
					reason: "negative number cannot be cast to unsigned value".to_string(),
				}
			})?
		}
		Number::Float(_) => {
			return Err(RenderError::UnsupportedValue {
				context: context.to_string(),
				kind: "numberValueNode",
				reason: "float cannot be cast to integer".to_string(),
			});
		}
	};
	if parsed > max {
		return Err(RenderError::UnsupportedValue {
			context: context.to_string(),
			kind: "numberValueNode",
			reason: format!("value `{parsed}` exceeds max `{max}`"),
		});
	}

	Ok(parsed)
}

/// Decodes a hex-encoded byte string, tolerating an optional `0x` prefix.
pub(crate) fn decode_base16(data: &str, context: &str) -> Result<Vec<u8>> {
	let digits = data.strip_prefix("0x").unwrap_or(data);
	if !digits.len().is_multiple_of(2) {
		return Err(RenderError::UnsupportedValue {
			context: context.to_string(),
			kind: "bytesValueNode",
			reason: "base16 byte string must have an even number of digits".to_string(),
		});
	}

	let mut bytes = Vec::with_capacity(digits.len() / 2);
	let mut chunk = [0u8; 2];
	for pair in digits.as_bytes().chunks_exact(2) {
		chunk.copy_from_slice(pair);
		let decoded = std::str::from_utf8(&chunk)
			.ok()
			.and_then(|pair| u8::from_str_radix(pair, 16).ok())
			.ok_or_else(|| {
				RenderError::UnsupportedValue {
					context: context.to_string(),
					kind: "bytesValueNode",
					reason: format!("invalid base16 byte string `{data}`"),
				}
			})?;
		bytes.push(decoded);
	}

	Ok(bytes)
}
